/// <summary>
/// Represents a customer packaging record
/// </summary>
public class AVARUMCustomerPackagingTable extends common
{

}

Method.Source:
/// <summary>
/// Determines if concurrent deletes should throw exception.
/// </summary>
/// <returns>true, if exception should be thrown; otherwise, false.</returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    return true;
}

/// <summary>
/// Gets the customer name.
/// </summary>
/// <returns>The customer name.</returns>
[SysClientCacheDataMethodAttribute(true)]
public display CustName custName()
{
    return CustTable::find(this.CustAccount).name();
}

/// <summary>
/// Gets the item name.
/// </summary>
/// <returns>The item name.</returns>
[SysClientCacheDataMethodAttribute(true)]
public display ItemName itemName()
{
    InventDimCombination inventDimCombination;

    inventDimCombination = InventDimCombination::findByDistinctProductVariant(this.DistinctProductVariant);
    return InventTable::find(inventDimCombination.ItemId).itemName();
}

/// <summary>
/// Gets the packaging description.
/// </summary>
/// <returns>The packaging description.</returns>
[SysClientCacheDataMethodAttribute(true)]
public display Description packageDescription()
{
    return AVARUMPackagingTable::find(this.Id).Description;
}

/// <summary>
/// Finds a customer packaging record by customer account, item ID, and packing ID.
/// </summary>                                           
/// <param name = "_packingId">The packing ID.</param>
/// <param name = "_custAccount">The customer account.</param>
/// <param name = "_distinctProductVariant">The distinct product variant.</param>
/// <param name = "_update">Whether to select the record for update.</param>
/// <returns>The found customer packaging record.</returns>
public static AVARUMCustomerPackagingTable find(AVARUMPackagingId _packingId, CustAccount _custAccount, RefRecId _distinctProductVariant, boolean _update = false)
{
    AVARUMCustomerPackagingTable customerPackaging;

    customerPackaging.selectForUpdate(_update);

    select firstonly customerPackaging
    where customerPackaging.Id == _packingId && 
        customerPackaging.CustAccount == _custAccount &&
        customerPackaging.DistinctProductVariant == _distinctProductVariant;

    return customerPackaging;
}

/// <summary>
/// Finds the email associated with a customer account and item ID.
/// </summary>
/// <param name = "_custAccount">The customer account.</param>
/// <param name = "_itemId">The item ID.</param>
/// <returns>The email address.</returns>
public static Email findEmailByDisplayProductNumber(CustAccount _custAccount, EcoResProductDisplayProductNumber _displayProductNumber)
{        
    RefRecId distinctProductVariant;

    distinctProductVariant = EcoResProduct::findByDisplayProductNumber(_displayProductNumber).RecId;

    return AVARUMCustomerPackagingTable::findEmail(_custAccount, distinctProductVariant);
}

/// <summary>
/// Finds the email associated with a customer account and distinct product variant.
/// </summary>
/// <param name = "_custAccount">The customer account.</param>
/// <param name = "_distinctProductVariant">The distinct product variant.</param>
/// <returns>The email address.</returns>
public static Email findEmail(CustAccount _custAccount, RefRecId _distinctProductVariant)
{
    AVARUMCustomerPackagingTable customerPackaging;

    select firstonly Email from customerPackaging
    where customerPackaging.Email && 
        customerPackaging.CustAccount == _custAccount &&
        customerPackaging.DistinctProductVariant == _distinctProductVariant;

    return customerPackaging.Email;
}

/// <summary>
/// Validates the specified field.
/// </summary>
/// <param name = "_fieldIdToCheck">The field ID to check.</param>
/// <returns>True if the field is valid; otherwise, false.</returns>
public boolean validateField(FieldId _fieldIdToCheck)
{
    boolean ret;

    ret = super(_fieldIdToCheck);

    switch (_fieldIdToCheck)
    {
        case fieldNum(AVARUMCustomerPackagingTable, Email):
            if (this.Email && !Global::validateEMail_AVA(this.Email))
            {
                ret = false;
                Global::error(strFmt("@AVARUM:EmailInvalid", this.Email));
            }
            break;
        case fieldNum(AVARUMCustomerPackagingTable, configId):
            ret=this.checkOrAssignDistinctProductVariantRecid();
            break;
    }

    return ret;
}

