    /// <summary>
    /// Returns the product search name.
    /// </summary>
    /// <returns>The search name of the product.</returns>
    [SysClientCacheDataMethodAttribute(true)]
    public display EcoResProductSearchName productSearchName()
    {
        EcoResDistinctProductVariant distinctProductVariant;
        distinctProductVariant = EcoResDistinctProductVariant::find(this.DistinctProductVariant);

        return distinctProductVariant.SearchName;
    }

private boolean checkOrAssignDistinctProductVariantRecid(boolean _onlyCheck=false)
{
    boolean rc=true;
    InventDimCombination locInventDimCombination;
    InventDim locInventDim;

    select locInventDimCombination
        join locInventDim
        where locInventDimCombination.ItemId==this.itemId
          && locInventDimCombination.inventDimId==locInventDim.inventDimId
          &&locInventDim.configId==this.ConfigId;

    if (_onlyCheck)
    {
        if (!locInventDimCombination.DistinctProductVariant)
        {
            rc=checkFailed("Variante ungültig (Variante ist in Produktvariante nicht vorhanden!)");
        }
    }
    else
    {
        this.DistinctProductVariant=locInventDimCombination.DistinctProductVariant;
    }
    return rc;        
}

/// <summary>
/// Modified assign distinctProductVariantReci
/// </summary>
/// <param name = "_fieldId">FieldId</param>
public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch(_fieldId)
    {
        case fieldNum(AVARUMCustomerPackagingTable, configId):
            this.checkOrAssignDistinctProductVariantRecid();
            break;
    }
}
